public class NewsPublisher {
    private final List<EmailSubscriber> subscribers = new ArrayList<>();

    public void subscribe(EmailSubscriber s) {
        subscribers.add(s);
    }

    public void publish(String headline) {
        for (EmailSubscriber s : subscribers) {
            s.update(headline);
        }
    }
}

